/* @autogenerated */
import { computed, Directive, input, signal, TemplateRef, viewChild } from '@angular/core';
import { FormControl } from '@angular/forms';
import { BaseAction } from './base-action';

/**
 * Base de las acciones con formulario (crear y editar): valores fijados u ocultos por el contexto,
 * el control del formulario y el estado de guardado.
 *
 * La plantilla de la subclase declara `#formTemplate` con el formulario.
 */
@Directive()
export abstract class BaseFormAction<T> extends BaseAction<T> {
  override readonly render = viewChild<TemplateRef<any>>('formTemplate');

  fixed = input<{ [key: string]: any }>();
  hidden = input<{ [key: string]: any }>();
  fixedProperties = computed(() => Object.keys(this.fixed() || {}));
  hiddenProperties = computed(() => Object.keys(this.hidden() || {}));
  definedProperties = computed(() => ({ ...(this.hidden() || {}), ...(this.fixed() || {}) }));

  readonly form = new FormControl<T | undefined>(undefined);
  /** Guardado en curso: evita dobles envíos. */
  readonly saving = signal(false);
}
